#!/usr/bin/env bash
# Reproducible local AST graph; no LLM backend or API charges.
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.."
export GRAPHIFY_BACKEND=none
if [[ $# -eq 0 ]]; then
    uv tool run --from 'graphifyy[sql]==0.9.107' graphify extract . --code-only --max-workers 2
    uv tool run --from 'graphifyy[sql]==0.9.107' graphify export html
else
    uv tool run --from 'graphifyy[sql]==0.9.107' graphify "$@"
fi
# Reports are generated by the CLI but not needed for scoped queries.
rm -f graphify-out/GRAPH_REPORT.md
